          "الفصل عن الكلاب مؤشر رئيسي آخر. فغرفة انتظار تتشارك فيها القطط والكلاب المكان ترفع توتر القطط فوراً وبشكل ملموس. وبعض العيادات لديها مناطق انتظار منفصلة أو تنقل القطط مباشرة إلى غرفة الاستشارة عند وصولها. والتشخيص داخل العيادة يهمّ أيضاً: فالعيادة التي لديها تحاليل دم وتحليل بول وأشعة وموجات فوق صوتية في الموقع يمكنها إكمال معظم الفحوصات في زيارة واحدة، ما يعني وقتاً أقل لقطتك في بيئة غريبة وحصولك على الأجوبة في اليوم نفسه.",
          "وللحالات الطارئة، تحقّق مما إذا كانت العيادة لديها قدرة عناية حرجة حقيقية: سوائل وريدية، وعلاج بالأكسجين، وطبيب لديه خبرة بالطوارئ الشائعة في القطط مثل انسداد المسالك البولية والضيق التنفسي وتناول السموم. فأقرب عيادة تعمل 24 ساعة أقل أهمية من وجود عيادة لديها قدرة طوارئ داخلية حقيقية خلال ساعات العمل المعتادة.",
