          "وإذا كنت تخطط للسفر دولياً مع قطتك، فلدبي متطلبات تصدير محددة، ولدول الوجهة قواعد استيراد خاصة تتضمن عادةً تطعيم داء الكلب والشريحة الإلكترونية واختبارات الأجسام المضادة في الدم (للاتحاد الأوروبي والمملكة المتحدة) وشهادة صحية رسمية يوقّعها طبيب معتمد خلال فترة قصيرة قبل المغادرة. والعيادة الجيدة ستعرف هذه المتطلبات وتساعدك في تخطيط الجدول الزمني مبكراً، لأن بعض الاختبارات، خصوصاً اختبار الأجسام المضادة لداء الكلب، يجب إجراؤها أشهراً قبل السفر.",
          "القطط الضالة والمنقذة شائعة في دبي، ويتبنّى كثير من المقيمين واحدة منها. وإذا أحضرت حديثاً قطة ضالة أو منقذة إلى المنزل، فالفحص الصحي الكامل ضروري: اختبار فيروس نقص المناعة القططي (FIV) وفيروس اللوكيميا القططي (FeLV)، وعلاج الطفيليات، والتطعيم، وتقييم الأسنان. فالقطط الضالة تحمل غالباً مشكلات صحية خفية يمكن إدارتها إذا اكتُشفت مبكراً.",
