          'يؤثر FIV على جهاز المناعة بطريقة شبيهة بتأثير فيروس نقص المناعة البشري في الإنسان: فالقطط المصابة قد تعيش سنوات طويلة بجودة حياة جيدة، خصوصاً إذا بقيت في الداخل وأُديرت بعناية. وينتقل FIV أساساً عبر جروح العض العميقة، لذا فخطر انتقاله إلى قطط أخرى في منزل لا يحدث فيه عراك منخفض نسبياً. ويمكن غالباً دمج القطط الموجبة لـ FIV مع القطط السالبة في منازل هادئة، مع ضرورة مناقشة ذلك مع طبيبك البيطري.',
