          "وبعض السلالات ممثلة بنسب أعلى بكثير: اللابرادور ريتريفر والروت وايلر والغولدن ريتريفر والستافوردشاير بول تيرير والويست هايلاند وايت تيرير. والكلاب زائدة الوزن معرّضة لخطر أعلى بكثير أيضاً. وقد وجدت دراسة عام 2008 نُشرت في Journal of the American Veterinary Medical Association أن حالة الجسم زائدة الوزن من أقوى مؤشرات مرض الرباط الصليبي.",
