          "تصوير القلب بالصدى هو تصوير بالموجات فوق الصوتية للقلب. وهو يتيح لنا النظر إلى بنية القلب ووظيفته في الزمن الحقيقي: مشاهدته ينبض، وقياس أحجام الحجرات، وتقييم حركة الصمامات، ورسم خرائط تدفق الدم بالدوبلر. وهو غير توغلي، ولا يتطلب تخديراً في معظم الحالات، ويمنحنا معلومات لا يستطيع فحص سريري أو صورة أشعة للصدر توفيرها.",
          "وفي عيادة مايكس فيت، نستخدم جهاز Mindray Vetus9، وهو من أكثر منصات الموجات فوق الصوتية البيطرية تقدماً. فتقنية Zone Sonography (ZST+) توفّر وضوح صورة استثنائياً حتى في الحيوانات ذات الصدور العميقة، وقدرة تصوير الدوبلر النسيجي (TDI) تتيح لنا كشف تغيرات دقيقة في وظيفة عضلة القلب لا تكون مرئية في تصوير صدى قياسي. ويتضمن قسم القلب المخصص دوبلر نابضاً وملوّن الجريان ودوبلر موجة مستمرة وقياساً آلياً لجزء القذف (Auto EF).",
          "وتحديداً، يتيح لنا تصوير القلب بالصدى تقييم: حجم كل حجرة قلبية وما إذا كانت ضمن الحدود الطبيعية؛ وما إذا كانت جُدر الحجرات مُتثخّنة كما في HCM أو رقيقة ومتوسعة كما في DCM؛ وكيف تنقبض عضلة القلب وتنبسط؛ ووجود وشدة شذوذات الصمامات؛ وما إذا كان الدم يرتجع عبر صمام غير محكم ومدى أهمية ذلك الارتجاع؛ ووجود انصباب في التامور (سائل حول القلب)؛ وعلامات ارتفاع ضغوط الامتلاء التي تدل على فشل قلبي وشيك أو مبكر.",
          "فللكافالير ذي لغط معروف، يخبرنا تصوير الصدى بالمرحلة التي هو فيها بحسب تصنيف ACVIM، وهو ما يحدد مباشرة ما إذا كان ينبغي بدء الدواء ومتى. وللراغدول بلا أي أعراض، قد يكشف تضخماً كبيراً في الأذين الأيسر يغيّر الإدارة بالكامل. وللكلب الذي يحضر بسعال، يميّز بين الأسباب القلبية والتنفسية، وهو تمييز يحدد نهج العلاج كله.",
