          "أهم تقدّم في طب قلب الحيوانات الصغيرة خلال العقد الماضي كان الأدلة من تجربة EPIC، التي أظهرت أن بدء البيموبندان في الكلاب ذات MMVD قبل الأعراض، وتحديداً تلك التي لديها تضخم قلبي لكن قبل ظهور الأعراض، يؤخر بشكل كبير بداية فشل القلب [1]. وقد غيّر هذا معيار الرعاية للكافالير وغيرها من الكلاب المصابة بمرض الصمام التاجي. ونحن الآن نبحث فعلياً عن الحدود القياسية في تصوير الصدى التي تحدد ما إذا كان الكلب مرشحاً لهذا التدخل.",
