          "السلالات قصيرة الوجه أكثر عرضة للحرارة بشكل كبير. فالبولدوغ والبَغ والبولدوغ الفرنسي والشي تزو والبوكسر لديها مجرى هوائي علوي مُعاق تشريحياً يحدّ من قدرتها على اللهاث بكفاءة. فآلية التبريد نفسها التي هي على الحدّ أصلاً في كلب عادي تصبح أكثر تقييداً في هذه السلالات. وخلال صيف دبي، لا ينبغي تمرين الكلاب قصيرة الوجه في الخارج مطلقاً بين الشروق والغروب إلا إذا كانت حرارة الجو أقل من 25 درجة مئوية.",
