          "القوباء الحلقية عدوى فطرية للجلد والشعر، وليست دودة طفيلية على الرغم من الاسم. والمصطلح الفني هو داء الفطريات الجلدية. وفي الكلاب، الكائن المسبب الأكثر شيوعاً هو Microsporum canis، وهو الفطر نفسه المسؤول عن معظم حالات القطط. وMicrosporum gypseum (كائن ترابي) وTrichophyton mentagrophytes يُحدّدان بتكرار أقل لكنهما يحدثان في الكلاب المعرّضة لتربة ملوّثة أو لقوارض صغيرة على التوالي.",
