          "وفي القطط، الجرعة السامّة أقل منها في الكلاب وكريات الدم الحمراء أكثر عرضة للتلف التأكسدي. وجميع الأشكال سامّة: نيئة ومطبوخة ومجففة ومسحوقة وفي الصلصات. والثوم أكثر سمّية بنحو خمس مرات لكل وحدة وزن من البصل. وطعام الأطفال ومرق اللحم والأطعمة المصنّعة قد تحتوي مسحوق بصل أو ثوم بكميات تضرّ قطة إذا استُهلكت بانتظام.",
