          "الديفنباخيا (قصبة البكم) نبات داخلي شائع جداً في دبي. وهي تحتوي بلورات أكسالات الكالسيوم غير القابلة للذوبان التي تسبب تهيّجاً فموياً شديداً وسيلان لعاب وحكّاً عند الفم وصعوبة بلع وتقيؤاً. ومع أنها نادراً ما تكون مهددة للحياة، فالألم الفموي شديد وتحتاج القطط إلى علاج بيطري للراحة.",
