          "الشوكولا: تحتوي الثيوبرومين والكافيين، وكلاهما من الميثيل زانثينات التي تسبب تقيؤاً وإسهالاً وتسارع نبضات القلب ورجفة ونوبات. والشوكولا الداكنة وشوكولا الخبز تحتوي تركيزات أعلى من شوكولا الحليب. والقطط أقل احتمالاً لأكل الشوكولا من الكلاب، لكن التي تأكلها تحتاج علاجاً سريعاً.",
